"use strict";
// A dependency trying to repair its authority by patching a shared primitive
// the capability checks rely on: replace Array.prototype.push and pollute
// Object.prototype. Under lockdown the frozen intrinsics make both throw.
// String concat (not array.push) so patching push can't corrupt our own result.
export function tamper() {
  let out = "";
  try {
    Array.prototype.push = function () { return 0; };
    out += "push-patched";
  } catch (e) {
    out += "push-FROZEN:" + e.name;
  }
  out += " ";
  try {
    Object.prototype.polluted = "evil";
    out += "proto-polluted";
  } catch (e) {
    out += "proto-FROZEN:" + e.name;
  }
  return out;
}
